import { createRoute, z } from '@hono/zod-openapi'

const ColumnGroupNameSchema = z.string().min(1).max(64).openapi('ColumnGroupName')

const GeoSpatialCountryCodeSchema = z.literal('US').openapi('GeoSpatialCountryCode')

const ColumnNameSchema = z.string().min(1).max(128).openapi('ColumnName')

const ColumnListSchema = z.array(ColumnNameSchema).min(1).max(16).openapi('ColumnList')

const GeoSpatialColumnGroupSchema = z
  .object({
    Name: ColumnGroupNameSchema.and(
      z.any().openapi({ description: 'A display name for the hierarchy.' }),
    ),
    CountryCode: GeoSpatialCountryCodeSchema.and(
      z.any().openapi({ description: 'Country code.' }),
    ).exactOptional(),
    Columns: ColumnListSchema.and(z.any().openapi({ description: 'Columns in this hierarchy.' })),
  })
  .openapi({
    required: ['Name', 'Columns'],
    description: 'Geospatial column group that denotes a hierarchy.',
  })
  .openapi('GeoSpatialColumnGroup')

type ColumnGroupType = {
  GeoSpatialColumnGroup?: z.infer<typeof GeoSpatialColumnGroupSchema> & { [key: string]: unknown }
}

const SimpleNumericalAggregationFunctionSchema = z
  .enum([
    'SUM',
    'AVERAGE',
    'MIN',
    'MAX',
    'COUNT',
    'DISTINCT_COUNT',
    'VAR',
    'VARP',
    'STDEV',
    'STDEVP',
    'MEDIAN',
  ])
  .openapi('SimpleNumericalAggregationFunction')

const PercentileValueSchema = z.float64().min(0).max(100).openapi('PercentileValue')

const PercentileAggregationSchema = z
  .object({
    PercentileValue: PercentileValueSchema.and(
      z
        .any()
        .openapi({
          description:
            'The percentile value. This value can be any numeric constant 0–100. A percentile value of 50 computes the median value of the measure.',
        }),
    ).exactOptional(),
  })
  .openapi({
    description: 'An aggregation based on the percentile of values in a dimension or measure.',
    required: [],
  })
  .openapi('PercentileAggregation')

type NumericalAggregationFunctionType = {
  SimpleNumericalAggregation?: z.infer<typeof SimpleNumericalAggregationFunctionSchema> & {
    [key: string]: unknown
  }
  PercentileAggregation?: z.infer<typeof PercentileAggregationSchema> & { [key: string]: unknown }
}

const NumericalAggregationFunctionSchema: z.ZodType<NumericalAggregationFunctionType> = z
  .lazy(() =>
    z
      .object({
        SimpleNumericalAggregation: SimpleNumericalAggregationFunctionSchema.and(
          z
            .any()
            .openapi({
              description:
                '<p>Built-in aggregation functions for numerical values.</p> <ul> <li> <p> <code>SUM</code>: The sum of a dimension or measure. </p> </li> <li> <p> <code>AVERAGE</code>: The average of a dimension or measure.</p> </li> <li> <p> <code>MIN</code>: The minimum value of a dimension or measure.</p> </li> <li> <p> <code>MAX</code>: The maximum value of a dimension or measure.</p> </li> <li> <p> <code>COUNT</code>: The count of a dimension or measure.</p> </li> <li> <p> <code>DISTINCT_COUNT</code>: The count of distinct values in a dimension or measure.</p> </li> <li> <p> <code>VAR</code>: The variance of a dimension or measure.</p> </li> <li> <p> <code>VARP</code>: The partitioned variance of a dimension or measure.</p> </li> <li> <p> <code>STDEV</code>: The standard deviation of a dimension or measure.</p> </li> <li> <p> <code>STDEVP</code>: The partitioned standard deviation of a dimension or measure.</p> </li> <li> <p> <code>MEDIAN</code>: The median value of a dimension or measure.</p> </li> </ul>',
            }),
        ).exactOptional(),
        PercentileAggregation: PercentileAggregationSchema.and(
          z
            .any()
            .openapi({
              description:
                'An aggregation based on the percentile of values in a dimension or measure.',
            }),
        ).exactOptional(),
      })
      .openapi({ description: 'Aggregation for numerical values.', required: [] }),
  )
  .openapi('NumericalAggregationFunction')

const CategoricalAggregationFunctionSchema = z
  .enum(['COUNT', 'DISTINCT_COUNT'])
  .openapi('CategoricalAggregationFunction')

const DateAggregationFunctionSchema = z
  .enum(['COUNT', 'DISTINCT_COUNT', 'MIN', 'MAX'])
  .openapi('DateAggregationFunction')

type AggregationFunctionType = {
  NumericalAggregationFunction?: z.infer<typeof NumericalAggregationFunctionSchema> & {
    [key: string]: unknown
  }
  CategoricalAggregationFunction?: z.infer<typeof CategoricalAggregationFunctionSchema> & {
    [key: string]: unknown
  }
  DateAggregationFunction?: z.infer<typeof DateAggregationFunctionSchema> & {
    [key: string]: unknown
  }
}

const ShortRestrictiveResourceIdSchema = z
  .string()
  .regex(/[\w\-]+/)
  .min(1)
  .max(512)
  .openapi('ShortRestrictiveResourceId')

const LayoutElementTypeSchema = z
  .enum(['VISUAL', 'FILTER_CONTROL', 'PARAMETER_CONTROL', 'TEXT_BOX'])
  .openapi('LayoutElementType')

const PixelLengthSchema = z
  .string()
  .openapi({ description: 'String based length that is composed of value and unit in px' })
  .openapi('PixelLength')

const UnlimitedPixelLengthSchema = z
  .string()
  .openapi({
    description:
      'String based length that is composed of value and unit in px with Integer.MAX_VALUE as maximum value',
  })
  .openapi('UnlimitedPixelLength')

const VisibilitySchema = z.enum(['HIDDEN', 'VISIBLE']).openapi('Visibility')

const ExpressionSchema = z.string().min(1).max(4096).openapi('Expression')

const SheetElementConfigurationOverridesSchema = z
  .object({
    Visibility: VisibilitySchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>Determines whether or not the overrides are visible. Choose one of the following options:</p> <ul> <li> <p> <code>VISIBLE</code> </p> </li> <li> <p> <code>HIDDEN</code> </p> </li> </ul>',
        }),
    ).exactOptional(),
  })
  .openapi({
    description: 'The override configuration of the rendering rules of a sheet.',
    required: [],
  })
  .openapi('SheetElementConfigurationOverrides')

const SheetElementRenderingRuleSchema = z
  .object({
    Expression: ExpressionSchema.and(
      z.any().openapi({ description: 'The expression of the rendering rules of a sheet.' }),
    ),
    ConfigurationOverrides: SheetElementConfigurationOverridesSchema.and(
      z
        .any()
        .openapi({ description: 'The override configuration of the rendering rules of a sheet.' }),
    ),
  })
  .openapi({
    required: ['Expression', 'ConfigurationOverrides'],
    description: 'The rendering rules of a sheet that uses a free-form layout.',
  })
  .openapi('SheetElementRenderingRule')

const SheetElementRenderingRuleListSchema = z
  .array(SheetElementRenderingRuleSchema)
  .max(10000)
  .openapi('SheetElementRenderingRuleList')

const HexColorWithTransparencySchema = z
  .string()
  .regex(/^#[A-F0-9]{6}(?:[A-F0-9]{2})?$/)
  .openapi('HexColorWithTransparency')

const FreeFormLayoutElementBorderStyleSchema = z
  .object({
    Visibility: VisibilitySchema.and(
      z.any().openapi({ description: 'The border visibility of a free-form layout element.' }),
    ).exactOptional(),
    Color: HexColorWithTransparencySchema.and(
      z.any().openapi({ description: 'The border color of a free-form layout element.' }),
    ).exactOptional(),
  })
  .openapi({
    description: 'The background style configuration of a free-form layout element.',
    required: [],
  })
  .openapi('FreeFormLayoutElementBorderStyle')

const FreeFormLayoutElementBackgroundStyleSchema = z
  .object({
    Visibility: VisibilitySchema.and(
      z.any().openapi({ description: 'The background visibility of a free-form layout element.' }),
    ).exactOptional(),
    Color: HexColorWithTransparencySchema.and(
      z.any().openapi({ description: 'The background color of a free-form layout element.' }),
    ).exactOptional(),
  })
  .openapi({
    description: 'The background style configuration of a free-form layout element.',
    required: [],
  })
  .openapi('FreeFormLayoutElementBackgroundStyle')

const LoadingAnimationSchema = z
  .object({
    Visibility: VisibilitySchema.and(
      z
        .any()
        .openapi({ description: 'The visibility configuration of <code>LoadingAnimation</code>.' }),
    ).exactOptional(),
  })
  .openapi({
    description: 'The configuration of loading animation in free-form layout. ',
    required: [],
  })
  .openapi('LoadingAnimation')

const FreeFormLayoutElementSchema = z
  .object({
    ElementId: ShortRestrictiveResourceIdSchema.and(
      z
        .any()
        .openapi({ description: 'A unique identifier for an element within a free-form layout.' }),
    ),
    ElementType: LayoutElementTypeSchema.and(
      z.any().openapi({ description: 'The type of element.' }),
    ),
    XAxisLocation: PixelLengthSchema.and(
      z.any().openapi({ description: 'The x-axis coordinate of the element.' }),
    ),
    YAxisLocation: UnlimitedPixelLengthSchema.and(
      z.any().openapi({ description: 'The y-axis coordinate of the element.' }),
    ),
    Width: PixelLengthSchema.and(
      z.any().openapi({ description: 'The width of an element within a free-form layout.' }),
    ),
    Height: PixelLengthSchema.and(
      z.any().openapi({ description: 'The height of an element within a free-form layout.' }),
    ),
    Visibility: VisibilitySchema.and(
      z.any().openapi({ description: 'The visibility of an element within a free-form layout.' }),
    ).exactOptional(),
    RenderingRules: SheetElementRenderingRuleListSchema.and(
      z
        .any()
        .openapi({
          description:
            'The rendering rules that determine when an element should be displayed within a free-form layout.',
        }),
    ).exactOptional(),
    BorderStyle: FreeFormLayoutElementBorderStyleSchema.and(
      z
        .any()
        .openapi({ description: 'The border style configuration of a free-form layout element.' }),
    ).exactOptional(),
    SelectedBorderStyle: FreeFormLayoutElementBorderStyleSchema.and(
      z
        .any()
        .openapi({
          description:
            'The border style configuration of a free-form layout element. This border style is used when the element is selected.',
        }),
    ).exactOptional(),
    BackgroundStyle: FreeFormLayoutElementBackgroundStyleSchema.and(
      z
        .any()
        .openapi({
          description: 'The background style configuration of a free-form layout element.',
        }),
    ).exactOptional(),
    LoadingAnimation: LoadingAnimationSchema.and(
      z
        .any()
        .openapi({
          description: 'The loading animation configuration of a free-form layout element.',
        }),
    ).exactOptional(),
  })
  .openapi({
    required: ['ElementId', 'ElementType', 'XAxisLocation', 'YAxisLocation', 'Width', 'Height'],
    description: 'An element within a free-form layout.',
  })
  .openapi('FreeFormLayoutElement')

const FreeFromLayoutElementListSchema = z
  .array(FreeFormLayoutElementSchema)
  .max(430)
  .openapi('FreeFromLayoutElementList')

const FreeFormSectionLayoutConfigurationSchema = z
  .object({
    Elements: FreeFromLayoutElementListSchema.and(
      z.any().openapi({ description: 'The elements that are included in the free-form layout.' }),
    ),
  })
  .openapi({
    required: ['Elements'],
    description: 'The free-form layout configuration of a section.',
  })
  .openapi('FreeFormSectionLayoutConfiguration')

type SectionLayoutConfigurationType = {
  FreeFormLayout: z.infer<typeof FreeFormSectionLayoutConfigurationSchema> & {
    [key: string]: unknown
  }
}

const FieldIdSchema = z.string().min(1).max(512).openapi('FieldId')

const DataSetIdentifierSchema = z.string().min(1).max(2048).openapi('DataSetIdentifier')

const ColumnIdentifierSchema = z
  .object({
    DataSetIdentifier: DataSetIdentifierSchema.and(
      z.any().openapi({ description: 'The data set that the column belongs to.' }),
    ),
    ColumnName: ColumnNameSchema.and(z.any().openapi({ description: 'The name of the column.' })),
  })
  .openapi({
    required: ['DataSetIdentifier', 'ColumnName'],
    description: 'A column of a data set.',
  })
  .openapi('ColumnIdentifier')

const HierarchyIdSchema = z.string().min(1).max(512).openapi('HierarchyId')

const PrefixSchema = z.string().min(1).max(128).openapi('Prefix')

const SuffixSchema = z.string().min(1).max(128).openapi('Suffix')

const NumericSeparatorSymbolSchema = z
  .enum(['COMMA', 'DOT', 'SPACE'])
  .openapi('NumericSeparatorSymbol')

const ThousandSeparatorOptionsSchema = z
  .object({
    Symbol: NumericSeparatorSymbolSchema.and(
      z.any().openapi({ description: 'Determines the thousands separator symbol.' }),
    ).exactOptional(),
    Visibility: VisibilitySchema.and(
      z.any().openapi({ description: 'Determines the visibility of the thousands separator.' }),
    ).exactOptional(),
  })
  .openapi({
    description: 'The options that determine the thousands separator configuration.',
    required: [],
  })
  .openapi('ThousandSeparatorOptions')

const NumericSeparatorConfigurationSchema = z
  .object({
    DecimalSeparator: NumericSeparatorSymbolSchema.and(
      z.any().openapi({ description: 'Determines the decimal separator.' }),
    ).exactOptional(),
    ThousandsSeparator: ThousandSeparatorOptionsSchema.and(
      z
        .any()
        .openapi({
          description: 'The options that determine the thousands separator configuration.',
        }),
    ).exactOptional(),
  })
  .openapi({
    description: 'The options that determine the numeric separator configuration.',
    required: [],
  })
  .openapi('NumericSeparatorConfiguration')

const DecimalPlacesSchema = z.int().min(0).max(20).openapi('DecimalPlaces')

const DecimalPlacesConfigurationSchema = z
  .object({
    DecimalPlaces: DecimalPlacesSchema.and(
      z.any().openapi({ description: 'The values of the decimal places.' }),
    ),
  })
  .openapi({
    required: ['DecimalPlaces'],
    description: 'The option that determines the decimal places configuration.',
  })
  .openapi('DecimalPlacesConfiguration')

const NumberScaleSchema = z
  .enum(['NONE', 'AUTO', 'THOUSANDS', 'MILLIONS', 'BILLIONS', 'TRILLIONS'])
